from research_helpers import source, decision, write_batch

rows = [
 ('c0473','quarantine','Quarantine','https://twilightzone.fandom.com/wiki/Quarantine','Twilight Zone Wiki contributors','Biological gestalt and psychic medicine replace the earlier mechanical civilization.','The indexed account is used; direct opening returned 402 and was respected. No general production/access rule is established.','needs_evidence','Psychic medicine and an ecological farm settlement do not establish labor-independent material provision.','Advanced human abilities are still human activity; neither a utopia label nor rejection of machines supplies a zero-variant employment policy.'),
 ('c0474','human-operators','The Human Operators','https://theouterlimits.fandom.com/wiki/The_Human_Operators','Outer Limits Wiki contributors','Sentient ships keep human captives to perform necessary repair functions.','Machine authority and life support do not establish dispensable labor or a supported nonworking population.','boundary_case','The human operators do actual useful technical work for their captor ships.','Captivity under an AI is not sufficient for a post-work order; maintaining life so a captive can work is different from decoupled access.'),
 ('c0475','camp','The Camp: Plot','https://www.imdb.com/title/tt0667962/plotsummary/','IMDb plot contributors','Prisoners repair failing equipment and process low-priority fuel; guards need repairs and food is scarce.','The alien departure is not proof of automatic labor replacement. Only bounded public synopsis passages were read.','boundary_case','The Camp’s declining fuel-production prison still relies on real human repairs and processing.','Obsolete demand and pointless oppression are not sufficient evidence that relevant productive labor has been technologically replaced.'),
 ('c0476','stream','Stream of Consciousness','https://theouterlimits.fandom.com/wiki/Stream_of_Consciousness','Outer Limits Wiki contributors','Neural access to knowledge excludes people whose brains cannot connect.','An information network is not automatically food, housing or shared productive ownership.','needs_evidence','The Stream’s knowledge access does not establish ordinary material distribution.','A neural interface and disability-based exclusion do not by themselves show labor-independent necessities.'),
 ('c0477','futurama-robots','Robots','https://futurama.fandom.com/wiki/Robots','Futurama Wiki contributors','Robots perform many menial jobs alongside useful human and alien work.','Individual episodes and alternate futures have different policies; the broad Earth aggregate is not homogeneous.','needs_evidence','Futurama’s robot labor does not settle Earth’s ordinary household access rules.','Task replacement and human/alien employment remain mixed; no general income floor or employment-preservation constitution is verified.'),
 ('c0478','bot-planet','Fear of a Bot Planet','https://en.wikipedia.org/wiki/Fear_of_a_Bot_Planet','Wikipedia contributors','Chapek 9 is a robot separatist population with no permanent human community established.','Temporary visitors and a working robot society cannot be counted as a human leisure population.','boundary_case','Chapek 9 does not supply an applicable supported human population.','Robot personhood and separatist government do not establish a justified human nonworking denominator or material-support economy.'),
 ('c0479','bots-bees','The Bots and the Bees','https://en.wikipedia.org/wiki/The_Bots_and_the_Bees','Wikipedia contributors','Robot parenthood and vocational identity concern Bender and Ben.','Robot reproduction and individual employment are not a distinct household-access constitution.','boundary_case','Robot reproduction and occupational identity do not establish a new post-work society.','The episode’s personal family story is not a population-level material regime.'),
 ('c0480','jetsons','List of The Jetsons characters','https://en.wikipedia.org/wiki/List_of_The_Jetsons_characters','Wikipedia contributors','George has a very short button-pushing workweek under an employer.','Different jokes give different hours; short hours are not a nonworking share or proof the button operation is deliberately unnecessary.','boundary_case','A short workweek and domestic convenience do not by themselves remove wages as the main access mechanism.','No verified alternative income/provision rule or intentional make-work policy is supplied by the quick reference.'),
 ('c0481','unity','Auto Erotic Assimilation','https://rickandmorty.fandom.com/wiki/Auto_Erotic_Assimilation','Rick and Morty Wiki contributors','A biological hive mind improves conditions while controlling embodied people.','Biological assimilation is not automatically AI production, and the inhabitants continue performing activity.','needs_evidence','Unity’s control and improved living conditions do not establish automated material production and allocation.','A biological hive mind must not be scored as external AI merely because its subjects lose individuality.'),
 ('c0482','microverse','Microverse Battery','https://rickandmorty.fandom.com/wiki/Microverse_Battery','Rick and Morty Wiki contributors','Biological inhabitants generate power for an external owner; nested universes shift that labor to other people.','Outsourced biological slave labor must not be erased as automation. The reference concerns the battery, not all Rick technologies.','boundary_case','The Microverse’s power comes from real coerced biological activity.','Creating a nested slave universe shifts labor rather than eliminating it; Rick’s technological power alone does not establish a post-work support order.'),
 ('c0483','citadel','The Ricklantis Mixup','https://en.wikipedia.org/wiki/The_Ricklantis_Mixup','Wikipedia contributors','Citadel workers manufacture wafers and compete for promotion under corporate hierarchy.','The intelligence of every Rick does not prove an available implemented replacement for every job or an intentional employment policy.','needs_evidence','The Citadel’s useful factory work and inequality do not establish a verified zero variant or post-work distribution.','Potential genius-level capacity is not the same as an actual complete automation alternative.'),
 ('c0484','pantheon-ui','The World to Come','https://pantheon-amc.fandom.com/wiki/The_World_to_Come','Pantheon Wiki contributors','Twenty-years-later uploaded society has embodied/UI conflict and different machine-operation permissions.','Active human uploads are recognized, but copying minds and legal admission do not settle their resource allocation.','needs_evidence','The mature uploaded-intelligence society lacks a clear support/access constitution in the quick reference.','The early exploited uploads, mature society and much later simulation project require different scopes; they are not averaged.')
]
S = [source('src-b65-'+sid,title,author,url,'tv_reference_indexed','Bounded public synopsis or character/lore passage read',claim,limitation) for cid,sid,title,url,author,claim,limitation,status,reason,analysis in rows]
D = [decision(cid,status,reason,['src-b65-'+sid],analysis=analysis,follow_up='Continue the queue without full fiction or series reconstruction; reopen only for a readily available economic reference.') for cid,sid,title,url,author,claim,limitation,status,reason,analysis in rows]
S.append(source('src-camp-obsolete-fuel-dialogue','The Camp subtitles','Episode dialogue transcribed by Subtitle Cat','https://www.subtitlecat.com/subs/1155/The%20Outer%20Limits_S03E07_The%20Camp.srt%20-%202.html','primary_tv_dialogue_transcription_indexed','Bounded obsolete-fuel and repair/food exchange read','The fuel is low priority and its ships are obsolete, while the guards require repairs.','Obsolete demand does not itself show automated replacement or a work-independent floor; no whole subtitle file read.'))
D[2]['source_ids'].append('src-camp-obsolete-fuel-dialogue')
write_batch(65,[f'c{i:04}' for i in range(473,485)],S,[],D,[
 'Twelve concise dispositions; no unclear economy is rescued by reading a whole episode or story.',
 'Quarantine and Camp direct opens returned 402 and were respected; bounded indexed references remained usable.',
 'A short workweek is not a nonworking census. Biological hive minds, slave universes and human repair labor do not automatically become robot provision.',
 'Real-world Pantheon job listings and speculative commentary about future uploading were discarded. The mature UI society remains distinct from the next far-future project lead.'
])
